// Получаем данные
const aiResponse = $json.output || $json.aiResponse || $json.message?.text || $json.message || $json.response || '';
const shouldAskConfirmation = $json.shouldAskConfirmation || false;
const learningPlan = $json.learningPlan || $json.план || [];
const userMessage = $json.userMessage || $json.message?.text || $json.text || '';
const isStartCommand = $json.isStartCommand || false;
const telegramChatId = $json.telegramChatId || $json.chatId || '';

let finalMessage = aiResponse;

// команда /start или пустое сообщение
if ((isStartCommand || !finalMessage.trim()) && !userMessage.toLowerCase().includes('да')) {
  finalMessage = 'Привет! Чему бы ты хотел научиться в рамках работы над текущим учебным проектом или подготовки к собеседованию? Укажите тему и ваш уровень (начальный, средний, продвинутый).';
}

// Если есть план и нужно подтверждение
if (learningPlan && learningPlan.length > 0 && shouldAskConfirmation) {
  const data = {
    план: learningPlan,
    текущая_тема: 0,
    изученные_понятия: []
  };

  // Если в ответе еще нет данных
  if (!finalMessage.includes('[ДАННЫЕ:')) {
    finalMessage += `\n\n[ДАННЫЕ:${JSON.stringify(data)}]`;
  }
}

// Если пользователь отказывается
if (userMessage.toLowerCase() === 'нет') {
  finalMessage = 'Хорошо, давайте создадим новый план. Что бы вы хотели изучить?';
}

return {
  chat_id: telegramChatId,
  text: finalMessage,
  needsTavilySearch: false
};

