const aiResponse = $json.output || '';
let searchQuery = '';

// Ищем tavily(query="...")
const match = aiResponse.match(/tavily\(query="([^"]+)"\)/);

if (match && match[1]) {

  searchQuery = match[1];
  console.log("Используем запрос из AI Agent:", searchQuery);
} else {

  console.log("Не найден tavily(query=...) в ответе, использую запасной запрос");
  searchQuery = "Основы тестирования программного обеспечения для начинающих";
}

// Получаем данные из Static Data 
const workflowStaticData = $getWorkflowStaticData('global');
const learningPlan = workflowStaticData.learningPlan || [];

return {
  tavilyQuery: searchQuery,
  format: `tavily(query="${searchQuery}")`,
  currentConcept: "первая_тема",
  learningPlan: learningPlan,
  workflowState: "обучение_начато",
  needsTavilySearch: true,
  telegramChatId: $json.telegramChatId || "",
  userMessage: $json.userMessage || ""
};

