const workflowStaticData = $getWorkflowStaticData('global');

if (!workflowStaticData.queries || !Array.isArray(workflowStaticData.queries)) {
  workflowStaticData.queries = [];
}

// ответ от ИИ агента
for (const item of $input.all()) {
  // ищем ответ
  let llmResponse = '';

  // 1. поле message
  if (item.json.message && typeof item.json.message === 'string') {
    llmResponse = item.json.message;
  }
  //  2. поле response
  else if (item.json.response && typeof item.json.response === 'string') {
    llmResponse = item.json.response;
  }
  //  3. строковое поле, содержащее "tavily"
  else {
    for (const key in item.json) {
      if (typeof item.json[key] === 'string' && item.json[key].includes('tavily')) {
        llmResponse = item.json[key];
        break;
      }
    }
  }

  // ответ не найден, пропускаем элемент
  if (!llmResponse) {
    console.log("Не удалось найти ответ ИИ агента в item.json");
    continue;
  }

  console.log("Найден ответ ИИ:", llmResponse.substring(0, 100) + "...");

  // Извлекаем  tavily(query="...")
  const tavilyRegex = /tavily\(query="([^"]+)"\)/;
  const match = llmResponse.match(tavilyRegex);

  if (match) {

    const searchQuery = match[1]; 
    console.log("Извлечен поисковый запрос:", searchQuery);

    // Проверяем, нет ли уже такого запроса
    if (!workflowStaticData.queries.includes(searchQuery)) {
      workflowStaticData.queries.push(searchQuery);
      console.log("Запрос добавлен в историю. Всего запросов:", workflowStaticData.queries.length);
    } else {
      console.log("Запрос уже существует в истории, пропускаем дубликат");
    }
  } else {

    console.log("Шаблон tavily(query=\"...\") не найден в ответе");
  }
}


return $input.all();
